import pandas as pd

sales = pd.DataFrame({
    "category": ["Toys", "Home", "Beauty", "Sports", "Electronics", "Garden"],
    "revenue": [12400, 31800, 20900, 18700, 45200, 2600],
})

share = (sales.set_index("category")["revenue"] / sales["revenue"].sum() * 100).round(1)
for name, value in share[share < 5].items():
    print(f"{name}: {value}%")

