def choose(family, n_categories):
    table = {"comparison": "bar", "trend": "line", "distribution": "histogram", "relationship": "scatter"}
    if family in table:
        return table[family]
    if family == "composition":
        return "stacked bar" if n_categories <= 5 else "sorted bar"
    raise ValueError(family)


print(choose("comparison", 6))
print(choose("composition", 3))
print(choose("composition", 9))
try:
    choose("map", 1)
except ValueError:
    print("error")
